import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ml import *
tee('m20'); reset()
n = Node('m20'); n.start(); c = n.client(); db = c.test
N = 200000
fill(db.u, N, lambda i: {'_id': i, 'email': f'user{i:06d}@x.com', 'name': f'name{i}', 'age': i % 80, 'city': f'c{i % 50}', 'pad': 'x' * 100})
db.u.create_index('email'); db.u.create_index([('age', 1), ('city', 1)])
print('== 一:覆盖查询:只要索引里有的字段,并且投影里去掉 _id(索引里不存 _id),docsExamined 就是 0')
msh(n, EXJS + 'var e = db.u.find({email: "user000123@x.com"}, {email: 1, _id: 0}).explain("executionStats"); ex(e)', label='db.u.find({email: ...}, {email: 1, _id: 0})')
msh(n, EXJS + 'var e = db.u.find({email: "user000123@x.com"}, {email: 1}).explain("executionStats"); ex(e)', label='db.u.find({email: ...}, {email: 1})    // 投影里带着 _id')
msh(n, EXJS + 'var e = db.u.find({email: "user000123@x.com"}, {email: 1, name: 1, _id: 0}).explain("executionStats"); ex(e)', label='db.u.find({email: ...}, {email: 1, name: 1, _id: 0})    // name 不在索引里')
print('== 二:把 _id 放进索引,投影里留着 _id 也能覆盖;复合索引 {age, city} 覆盖对这两个字段的查询')
db.u.create_index([('email', 1), ('_id', 1)], name='email_id')
msh(n, EXJS + 'var e = db.u.find({email: "user000123@x.com"}, {email: 1}).hint("email_id").explain("executionStats"); ex(e)', label='hint("email_id") 的 db.u.find({email: ...}, {email: 1})')
msh(n, EXJS + 'var e = db.u.find({age: 30, city: "c10"}, {age: 1, city: 1, _id: 0}).explain("executionStats"); ex(e)', label='db.u.find({age: 30, city: "c10"}, {age: 1, city: 1, _id: 0})')
print('== 三:count 和聚合也能覆盖:count 走索引不读文档;$group 只用索引里的字段')
msh(n, EXJS + 'var e = db.u.explain("executionStats").aggregate([{$match: {age: 30}}, {$group: {_id: "$city", n: {$sum: 1}}}]); ex(e)', label='aggregate [{$match: {age: 30}}, {$group: {_id: "$city", n: {$sum: 1}}}]')
msh(n, EXJS + 'var e = db.u.explain("executionStats").aggregate([{$match: {age: 30}}, {$group: {_id: "$name", n: {$sum: 1}}}]); ex(e)', label='aggregate [{$match: {age: 30}}, {$group: {_id: "$name", n: {$sum: 1}}}]    // 需要 name')
msh(n, 'var e = db.u.explain("executionStats").count({age: 30}); ({stage: JSON.stringify(e.queryPlanner.winningPlan.stage), docsExamined: e.executionStats.totalDocsExamined, keysExamined: e.executionStats.totalKeysExamined})', label='db.u.explain("executionStats").count({age: 30})')
print('== 四:数组字段(multikey 索引)不能覆盖:索引里是拆开的元素,取不回原来的数组')
db.arr.insert_many([{'_id': i, 'tags': ['a%d' % (i % 10), 'b%d' % (i % 7)], 'k': i} for i in range(20000)])
db.arr.create_index('tags')
msh(n, EXJS + 'var e = db.arr.find({tags: "a3"}, {tags: 1, _id: 0}).explain("executionStats"); ex(e)', label='db.arr.find({tags: "a3"}, {tags: 1, _id: 0})')
msh(n, EXJS + 'var e = db.arr.find({tags: "a3"}, {k: 1, _id: 0}).explain("executionStats"); ex(e)', label='db.arr.find({tags: "a3"}, {k: 1, _id: 0})')
print('== 五:耗时对比:范围查询返回 age=30 的 2500 个文档,取 age 和 city 两个字段(覆盖)vs 再多取 name(要读文档),各 9 次中位数')
def t(proj): return bench(lambda: list(db.u.find({'age': 30}, proj)), 9)
cov = t({'age': 1, 'city': 1, '_id': 0}); fet = t({'age': 1, 'city': 1, 'name': 1, '_id': 0})
print(f'  覆盖 {{age, city, _id:0}}: {fm(cov)};需要 FETCH {{age, city, name, _id:0}}: {fm(fet)}')
e1 = jv(n, 'db.u.find({age: 30}, {age: 1, city: 1, _id: 0}).explain("executionStats").executionStats.totalDocsExamined'); e2 = jv(n, 'db.u.find({age: 30}, {age: 1, city: 1, name: 1, _id: 0}).explain("executionStats").executionStats.totalDocsExamined')
print(f'  docsExamined: 覆盖 {e1},FETCH {e2}')
print('== 六:什么会让覆盖失效:查询条件里有索引外的字段;排序字段在索引里则不影响')
msh(n, EXJS + 'var e = db.u.find({age: 30, name: "name30"}, {age: 1, _id: 0}).explain("executionStats"); ex(e)', label='db.u.find({age: 30, name: "name30"}, {age: 1, _id: 0})    // 条件里有 name')
msh(n, EXJS + 'var e = db.u.find({age: 30}, {age: 1, _id: 0}).sort({city: 1}).explain("executionStats"); ex(e)', label='db.u.find({age: 30}, {age: 1, _id: 0}).sort({city: 1})    // city 在索引里,可以覆盖并按索引顺序')
n.stop()
